import frappe
from frappe import _
from frappe.utils import flt
from qorg.qorg.shared_cost_allocation.reporting import in_selected,apply_view,chart_by,summary
def execute(filters=None):
 f=frappe._dict(filters or {});rules=frappe.get_all("Shared Cost Allocation Rule",filters={"company":f.company,"docstatus":1},pluck="name");rows=[]
 for name in rules:
  rule=frappe.get_doc("Shared Cost Allocation Rule",name)
  for t in rule.targets:
   if not t.allow_allocation or not in_selected(t.project,f,"project") or not in_selected(t.donor,f,"donor") or not in_selected(t.funding_agreement,f,"funding_agreement"):continue
   source=flt(frappe.db.sql("select coalesce(sum(source_amount),0) from `tabShared Cost Allocation Run` where docstatus=1 and posting_date between %s and %s and allocation_rule=%s",(f.from_date,f.to_date,name))[0][0]);actual=flt(frappe.db.sql("select coalesce(sum(e.allocated_amount),0) from `tabShared Cost Allocation Entry` e join `tabShared Cost Allocation Run` r on r.name=e.parent where r.docstatus=1 and r.posting_date between %s and %s and r.allocation_rule=%s and e.project=%s and e.budget_line=%s",(f.from_date,f.to_date,name,t.project,t.budget_line))[0][0]);planned=flt(t.fixed_amount) if rule.allocation_method=="Fixed Amount" else (source*flt(t.allocation_percentage)/100 if rule.allocation_method=="Fixed Percentage" else 0);planned=planned or flt(t.maximum_amount);rows.append({"rule":name,"project":t.project,"donor":t.donor,"funding_agreement":t.funding_agreement,"budget_line":t.budget_line,"method":rule.allocation_method,"planned":planned,"actual":actual,"variance":actual-planned})
 cols=[{"label":_("Rule"),"fieldname":"rule","fieldtype":"Link","options":"Shared Cost Allocation Rule","width":170,"sticky":1},{"label":_("Project"),"fieldname":"project","fieldtype":"Link","options":"Project","width":160,"sticky":1},{"label":_("Method"),"fieldname":"method","width":150},{"label":_("Donor"),"fieldname":"donor","fieldtype":"Link","options":"Donor","width":145},{"label":_("Funding Agreement"),"fieldname":"funding_agreement","fieldtype":"Link","options":"Funding Agreement","width":180},{"label":_("Budget Line"),"fieldname":"budget_line","fieldtype":"Link","options":"Budget Line","width":170},{"label":_("Planned Basis"),"fieldname":"planned","fieldtype":"Float","width":115},{"label":_("Actual"),"fieldname":"actual","fieldtype":"Currency","width":120},{"label":_("Variance"),"fieldname":"variance","fieldtype":"Currency","width":120}];return apply_view(cols,f.view_mode),rows,None,chart_by(rows,"project","actual",_("Actual")),summary([(_("Actual"),sum(flt(x["actual"]) for x in rows),"Currency","Green"),(_("Variance"),sum(flt(x["variance"]) for x in rows),"Currency","Orange")]),1
